import csv, io, json, os, sys
from datetime import datetime, timedelta, timezone


def load(p):
    with open(p, encoding="utf-8") as f:
        return json.load(f)


def read_exports(d):
    rows = []
    ed = os.path.join(d, "exports")
    for name in sorted(os.listdir(ed)):
        p = os.path.join(ed, name)
        if not name.endswith(".csv") or not os.path.isfile(p):
            continue
        with open(p, "rb") as f:
            text = f.read().decode("utf-8")
        if text.startswith("\ufeff"):
            text = text[1:]
        first = text.replace("\r\n", "\n").split("\n", 1)[0]
        delim = next((c for c in (",", ";", "\t") if c in first), ",")
        rd = csv.reader(io.StringIO(text, newline=""), delimiter=delim)
        header = None
        for rec in rd:
            if header is None:
                header = [h.strip() for h in rec]
                continue
            cells = [c.strip() for c in rec]
            if not any(cells):
                continue
            row = {}
            for h, c in zip(header, cells):
                row[h] = c if c != "" else None
            rows.append(row)
    return rows


def parse_time(s, fmt, off):
    s = s.strip()
    if fmt == "local":
        dt = datetime.strptime(s[:19].replace("T", " "), "%Y-%m-%d %H:%M:%S")
        return dt - parse_off(off)
    dt = datetime.strptime(s[:19], "%Y-%m-%dT%H:%M:%S")
    rest = s[19:]
    if rest.startswith("."):
        i = 1
        while i < len(rest) and rest[i].isdigit():
            i += 1
        rest = rest[i:]
    if rest in ("Z", "z", ""):
        return dt
    return dt - parse_off(rest)


def parse_off(o):
    sign = -1 if o[0] == "-" else 1
    h, m = o[1:].split(":")
    return sign * timedelta(hours=int(h), minutes=int(m))


def parse_dur(s, fmt):
    if fmt == "clock":
        t = 0
        for p in s.split(":"):
            t = t * 60 + int(p)
        return t
    return int(float(s))


def median(v):
    v = sorted(v)
    n = len(v)
    if n % 2:
        return v[n // 2]
    return (v[n // 2 - 1] + v[n // 2]) / 2


def r2(x):
    return round(x + 0.0, 2)


def to_code(v, rec):
    if rec is not None:
        return rec[v]
    return int(float(v)) if not v.lstrip("-").isdigit() else int(v)


def read_answer(q, ent, row, cb):
    t = q["type"]
    if t == "single":
        v = row.get(ent["column"])
        if v is None:
            return None
        c = to_code(v, ent.get("recode"))
        miss = {o["code"] for o in q["options"] if o.get("missing")}
        return None if c in miss else c
    if t == "age":
        v = row.get(ent["column"])
        if v is None:
            return None
        src = ent.get("source")
        if src == "band":
            return to_code(v, ent.get("recode"))
        age = int(float(v))
        if src == "birth_year":
            age = int(cb["reference_date"][:4]) - age
        for b in q["bands"]:
            if b["min"] <= age <= b["max"]:
                return b["code"]
        return None
    # multi
    rec = ent.get("recode")
    chosen = set()
    if "columns" in ent:
        for code, col in ent["columns"].items():
            if row.get(col) == "1":
                chosen.add(int(code))
    else:
        v = row.get(ent["column"])
        if v is not None:
            for e in v.split(ent["separator"]):
                e = e.strip()
                if e:
                    chosen.add(to_code(e, rec))
    excl = {o["code"] for o in q["options"] if o.get("exclusive")}
    if chosen - excl:
        chosen -= excl
    elif len(chosen) >= 2:
        chosen = set()
    miss = {o["code"] for o in q["options"] if o.get("missing")}
    chosen -= miss
    return chosen or None


def main():
    d, out = sys.argv[1], sys.argv[2]
    cb = load(os.path.join(d, "codebook.json"))
    wt = load(os.path.join(d, "weighting.json"))
    plan = load(os.path.join(d, "tables.json"))
    vkeys = list(cb["versions"].keys())
    stats = {k: dict(rows=0, duplicates=0, short_partials=0, speeders=0, complete=0, partial=0) for k in vkeys}

    recs = []
    for row in read_exports(d):
        v = row.get("form_version")
        m = cb["versions"][v]["meta"]
        rid = row.get(m["id"])
        complete = row.get(m["status"]) == m["complete"]
        t = parse_time(row[m["submitted"]], m["submitted_format"], m.get("utc_offset"))
        dur = parse_dur(row[m["duration"]], m["duration_format"]) if row.get(m["duration"]) is not None else 0
        lp = row.get(m["last_page"])
        lp = int(float(lp)) if lp is not None else 0
        stats[v]["rows"] += 1
        recs.append(dict(v=v, id=rid, complete=complete, t=t, dur=dur, lp=lp, row=row))

    best = {}
    for r in recs:
        b = best.get(r["id"])
        if b is None or (r["complete"], r["t"]) > (b["complete"], b["t"]):
            if b is not None:
                stats[b["v"]]["duplicates"] += 1
            best[r["id"]] = r
        else:
            stats[r["v"]]["duplicates"] += 1
    kept = []
    for r in best.values():
        if not r["complete"] and r["lp"] < cb["partial_min_page"]:
            stats[r["v"]]["short_partials"] += 1
        else:
            kept.append(r)
    med = {}
    for v in vkeys:
        ds = [r["dur"] for r in kept if r["v"] == v and r["complete"]]
        if ds:
            med[v] = median(ds)
    final = []
    for r in kept:
        if r["complete"] and r["dur"] * 5 < med[r["v"]] * 2:
            stats[r["v"]]["speeders"] += 1
        else:
            final.append(r)
    for r in final:
        stats[r["v"]]["complete" if r["complete"] else "partial"] += 1
    n = len(final)

    # answers
    qs = {q["id"]: q for q in cb["questions"]}
    for r in final:
        ans, asked = {}, {}
        for q in cb["questions"]:
            ent = q["versions"].get(r["v"])
            a = False
            if ent is not None and (r["complete"] or ent["page"] <= r["lp"]):
                a = True
                ai = q.get("ask_if")
                if ai:
                    pa = ans.get(ai["question"])
                    if not asked.get(ai["question"]) or pa is None:
                        a = False
                    else:
                        codes = set(ai["codes"])
                        s = pa if isinstance(pa, set) else {pa}
                        a = bool(s & codes)
            asked[q["id"]] = a
            ans[q["id"]] = read_answer(q, ent, r["row"], cb) if a else None
        r["ans"], r["asked"] = ans, asked

    def codes_of(q):
        return [o["code"] for o in (q["options"] if "options" in q else q["bands"])]

    # weighting
    w = [1.0] * n
    dims = []
    for dm in wt["dimensions"]:
        qid = dm["question"]
        present = {r["ans"][qid] for r in final if r["ans"][qid] is not None}
        tg = {int(k): float(v) for k, v in dm["targets"].items() if int(k) in present}
        tot = sum(tg.values())
        if not tg or tot == 0:
            continue
        share = {c: v / tot for c, v in tg.items()}
        cat = [final[i]["ans"][qid] if final[i]["ans"][qid] in share else None for i in range(n)]
        dims.append((share, cat))
    if n:
        for _ in range(wt["max_iterations"]):
            ok = True
            for share, cat in dims:
                T = sum(w[i] for i in range(n) if cat[i] is not None)
                W = {c: 0.0 for c in share}
                for i in range(n):
                    if cat[i] is not None:
                        W[cat[i]] += w[i]
                f = {c: share[c] * T / W[c] for c in share}
                for c in f:
                    if abs(f[c] - 1) > wt["tolerance"]:
                        ok = False
                for i in range(n):
                    if cat[i] is not None:
                        w[i] *= f[cat[i]]
            if ok:
                break
        m = sum(w) / n
        hi, lo = wt["cap"] * m, wt["floor"] * m
        w = [min(max(x, lo), hi) for x in w]
        m = sum(w) / n
        w = [x / m for x in w]

    summary = {
        "versions": [dict(version=k, **stats[k]) for k in vkeys],
        "respondents": n,
        "effective_n": r2(sum(w) ** 2 / sum(x * x for x in w)) if n else None,
        "weight_min": r2(min(w)) if n else None,
        "weight_max": r2(max(w)) if n else None,
    }

    # columns
    cols = [("total", lambda r: True)]
    for bq in plan["banner"]:
        q = qs[bq]
        miss = {o["code"] for o in q.get("options", []) if o.get("missing")}
        for c in codes_of(q):
            if c in miss:
                continue
            cols.append((f"{bq}:{c}", (lambda bq, c: lambda r: r["ans"][bq] == c)(bq, c)))

    tables = []
    for tb in plan["tables"]:
        q = qs[tb["question"]]
        qid = q["id"]
        opts = [o for o in q["options"] if not o.get("missing")]
        out_cols = []
        for cid, fn in cols:
            idx = [i for i, r in enumerate(final) if r["ans"][qid] is not None and fn(r)]
            wb = sum(w[i] for i in idx)
            vals = {}
            def has(i, codes):
                a = final[i]["ans"][qid]
                s = a if isinstance(a, set) else {a}
                return bool(s & set(codes))
            if not idx:
                for o in opts: vals[str(o["code"])] = None
                for nt in tb.get("nets", []): vals[nt["id"]] = None
                if tb.get("mean"): vals["mean"] = None
            else:
                for o in opts:
                    vals[str(o["code"])] = r2(100 * sum(w[i] for i in idx if has(i, [o["code"]])) / wb)
                for nt in tb.get("nets", []):
                    vals[nt["id"]] = r2(100 * sum(w[i] for i in idx if has(i, nt["codes"])) / wb)
                if tb.get("mean"):
                    sc = {o["code"]: o["score"] for o in opts}
                    vals["mean"] = r2(sum(w[i] * sc[final[i]["ans"][qid]] for i in idx) / wb)
            out_cols.append({"column": cid, "base": len(idx), "weighted_base": r2(wb), "values": vals})
        tables.append({"table": tb["id"], "columns": out_cols})

    with open(out, "w", encoding="utf-8") as f:
        json.dump({"survey": cb["survey"], "summary": summary, "tables": tables}, f, indent=1)


main()
